CREATE TABLE IF NOT EXISTS visitors (email TEXT PRIMARY KEY,created_at INTEGER NOT NULL,last_seen INTEGER NOT NULL,welcome_sent_at INTEGER);
CREATE TABLE IF NOT EXISTS visitor_sessions (token_hash TEXT PRIMARY KEY,email TEXT NOT NULL,created_at INTEGER NOT NULL,expires_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS sessions_expiry ON visitor_sessions(expires_at);
CREATE TABLE IF NOT EXISTS feedback (id TEXT PRIMARY KEY,email TEXT NOT NULL,rating INTEGER NOT NULL,message TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS reports (id TEXT PRIMARY KEY,email TEXT NOT NULL,source_type TEXT NOT NULL,total INTEGER NOT NULL,cars INTEGER NOT NULL,motorcycles INTEGER NOT NULL,buses INTEGER NOT NULL,trucks INTEGER NOT NULL,bicycles INTEGER NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS rate_limits (bucket TEXT PRIMARY KEY,hits INTEGER NOT NULL,expires_at INTEGER NOT NULL);
